<script setup>
import { ref,onMounted } from 'vue';
import { api } from '../api/index.js';
const items=ref([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref(null),dialog=ref(false);
const label=status=>({running:'执行中',preview:'预览',completed:'完成',failed:'失败',interrupted:'中断待核对',reconciled:'已核对',prepared:'结果待核对',queued:'排队',would_delete:'待清理',deleted:'已删除',absent:'种子已不存在',skipped:'已跳过'}[status]??status);
async function load(){loading.value=true;error.value='';try{const r=await api(`/qbittorrent/cleanup-history?page=${page.value}&pageSize=20`,{quiet:true});items.value=r.items;total.value=r.total;}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function show(id){try{detail.value=await api(`/qbittorrent/cleanup-history/${id}`);dialog.value=true;}catch{}}
onMounted(load);defineExpose({load});
</script>
<template><section class="panel"><div class="panel-header"><h2>清理执行记录</h2><el-button :loading="loading" @click="load">刷新执行记录</el-button></div><div class="panel-body"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="items" v-loading="loading"><el-table-column label="时间" width="170"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="操作" width="85"><template #default="{row}">{{row.dryRun?'预览':'清理'}}</template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}">{{label(row.status)}}</template></el-table-column><el-table-column prop="matchedCount" label="匹配" width="70"/><el-table-column prop="source" label="来源" width="85"/><el-table-column label="详情" width="90"><template #default="{row}"><el-button size="small" @click="show(row.id)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next" @current-change="load"/></div></section><el-dialog v-model="dialog" title="清理记录详情" width="min(900px, 95vw)"><template v-if="detail"><p>{{detail.deleteFiles?'请求同时删除文件':'保留下载文件'}} · {{label(detail.status)}}</p><p class="path">{{detail.sourceUrl}}</p><el-alert v-if="detail.error" :title="detail.error" type="warning" :closable="false"/><p class="muted">中断后仅核对种子是否存在，不重新执行删除；种子不存在不能证明文件已删除。</p><el-table :data="detail.items"><el-table-column prop="name" label="种子名称" min-width="160"/><el-table-column label="状态" width="135"><template #default="{row}">{{label(row.status)}}</template></el-table-column><el-table-column label="说明" min-width="180"><template #default="{row}">{{row.reason||row.error||''}}</template></el-table-column></el-table></template></el-dialog></template>
<style scoped>.el-pagination{margin-top:16px;}</style>
